post_tasks.data:
//测试响应码是否是200
apt.assert('response.raw.status==200');
//测试响应内容格式是否为json
// apt.assert('response.raw.type=="json"');
//测试响应时间是否小于等于1000ms
//apt.assert('response.raw.responseTime<=1000');
apt.test("响应时间小于 1000ms", function () {
  apt.expect(apt.response.responseTime).to.be.below(1000);
});
//测试响应Json对象的code是否为0
apt.assert('response.json.code==0');
//测试响应头Server是否为nginx
//apt.assert('response.headers["Server"] == "nginx"');
// 检测返回json对象的是否含有data字段
apt.assert('response.json.hasOwnProperty("data")');

//测试响应内容是否包含token
apt.assert('response.raw.responseText.indexOf("token") > -1');


//console.log(response.json.data.token)

//设置 X-token环境变量
apt.environment.set("token",  response.json.data.token);

//测试响应内容是否包含token
apt.assert('response.raw.responseText.indexOf("token") > -1');


//console.log(response.json.data.token)

//设置 X-token环境变量
apt.environment.set("token",  response.json.data.token);

pre_tasks.data:
apt.setRequestHeader("type", "reqeust");

var token = apt.environment.get("token");

apt.setRequestHeader("X-Token", token);

